// GENERATED by `npm run bake:props` from public/models/stations/mortar.glb — DO NOT EDIT BY HAND.
//
// ★ The sculpt as a SYNCHRONOUS factory, because three of its consumers do not run in a
// browser: `floraBounds` (the reticle's box), `mesh-icon` (the bag icon's software
// raster) and the node checks that read both. See `scripts/bake-flora-model.mts` for the
// argument in full. Re-bake after every picaso pass; the `.glb` remains the source.
//
// Positions are int16 over the model's own measured box (step ~2e-5 blocks). Normals are
// NOT baked — every consumer shades these flat and derives them from the positions.

import * as THREE from 'three'

const decode = (b64: string, stride: number, min: number[], max: number[]): Float32Array => {
  const raw = typeof atob === 'function'
    ? Uint8Array.from(atob(b64), c => c.charCodeAt(0))
    : Uint8Array.from(Buffer.from(b64, 'base64'))
  const q = new Int16Array(raw.buffer, raw.byteOffset, raw.byteLength / 2)
  const out = new Float32Array(q.length)
  for (let i = 0; i < q.length; i += stride) {
    for (let k = 0; k < stride; k++) out[i + k] = min[k] + ((q[i + k] + 32768) / 65535) * (max[k] - min[k])
  }
  return out
}

const mortarBodyGeo_P = ''
/** `Body` — 748 triangles. Base at the model's own origin, blocks as units. */
export const mortarBodyGeo = (): THREE.BufferGeometry => {
  const g = new THREE.BufferGeometry()
  g.setAttribute('position', new THREE.Float32BufferAttribute(
    decode(mortarBodyGeo_P, 3, [-0.349739, 0.000000, -0.361092], [0.364471, 0.620000, 0.349915]), 3))
  g.computeVertexNormals()
  return g
}

/** The model's own box across every part, measured at bake. Normalise through this. */
export const mortarBox = {
  min: [-0.34974, 0.00000, -0.36109] as const,
  max: [0.36447, 0.62000, 0.34992] as const,
}
